window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[49]={"id":"049","numero":49,"titre":"Puberté normale et pathologique","objectifs":[{"id":"49-1","rang":"A","rubrique":"Évaluation","titre":"Connaître le développement pubertaire normal","contenu":"<p>La <span class=\"kw-def\">puberté</span> est l'ensemble des phénomènes <strong>physiques, psychiques, mentaux et affectifs</strong> qui caractérisent la transition entre l'enfance et l'âge adulte. Sur le plan physique, elle est marquée par :</p>\n      <ul>\n        <li>Acquisition des <span class=\"kw-clinique\">caractères sexuels secondaires</span> ;</li>\n        <li>Maturation de la fonction sécrétoire gonadique ;</li>\n        <li>Acquisition des fonctions de reproduction ;</li>\n        <li>Accélération de la <span class=\"kw-clinique\">vitesse de croissance staturale</span> jusqu'à la taille définitive.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Repères normaux par sexe</h4>\n      <table >\n        <thead><tr><th>Repère</th><th>Fille 👧🏻</th><th>Garçon 👦🏻</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1er signe pubertaire</strong></td><td><span class=\"kw-clinique\">Thélarche</span> (bourgeon mammaire) — <span class=\"kw-chiffre\">8-13 ans</span></td><td>Augmentation du <span class=\"kw-clinique\">volume testiculaire</span> <span class=\"kw-chiffre\">≥ 4 mL</span> ou longueur <span class=\"kw-chiffre\">≥ 25 mm</span> — <span class=\"kw-chiffre\">9-14 ans</span></td></tr>\n          <tr><td><strong>Hormone-clé</strong></td><td><span class=\"kw-bio\">Œstrogènes</span> (sous <span class=\"kw-bio\">LH/FSH</span>)</td><td><span class=\"kw-bio\">FSH</span> (volume test.) puis <span class=\"kw-bio\">testostérone</span> (sous <span class=\"kw-bio\">LH</span>)</td></tr>\n          <tr><td><strong>Pic de croissance</strong></td><td>Dès <span class=\"kw-chiffre\">S2</span> (précoce) — <span class=\"kw-chiffre\">+8-10 cm/an</span></td><td>Décalé, vers <span class=\"kw-chiffre\">G3</span> — <span class=\"kw-chiffre\">+8-10 cm/an</span></td></tr>\n          <tr><td><strong>Ménarche / pilosité faciale</strong></td><td><span class=\"kw-clinique\">Ménarche</span> : ≈ <span class=\"kw-chiffre\">12,5 ans</span> (<span class=\"kw-chiffre\">2 ans</span> après thélarche)</td><td><span class=\"kw-clinique\">Pilosité faciale</span> + <span class=\"kw-clinique\">mue de la voix</span> : <span class=\"kw-chiffre\">14-15 ans</span></td></tr>\n          <tr><td><strong>Taille finale moyenne</strong></td><td><span class=\"kw-chiffre\">1m65</span> (≈ <span class=\"kw-chiffre\">16 ans</span>)</td><td><span class=\"kw-chiffre\">1m77</span> (≈ <span class=\"kw-chiffre\">18 ans</span>)</td></tr>\n          <tr><td><strong>Âge osseux pubertaire</strong></td><td><span class=\"kw-imagerie\">Âge osseux</span> <span class=\"kw-chiffre\">11 ans</span> (sésamoïde du pouce)</td><td><span class=\"kw-imagerie\">Âge osseux</span> <span class=\"kw-chiffre\">13 ans</span> (sésamoïde du pouce)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Durée moyenne de la puberté : <span class=\"kw-chiffre\">4 ans</span></strong> — l'<span class=\"kw-clinique\">irrégularité des cycles</span> est normale lors des <span class=\"kw-chiffre\">2 premières années</span> post-ménarche, mais <span class=\"kw-clinique\">les</span> cycles sont <strong>ovulatoires dès la 1ʳᵉ année</strong>.\n      </div>","frequence":1},{"id":"49-2","rang":"A","rubrique":"Définition","titre":"Définir les termes suivants pubarche, thélarche et ménarche","contenu":"<table >\n        <thead><tr><th>Terme</th><th>Définition</th><th>Repère d'âge</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Thélarche</strong></td>\n            <td>Apparition du <span class=\"kw-clinique\">bourgeon mammaire</span> chez la fille (secondaire aux <span class=\"kw-bio\">œstrogènes</span>, sous contrôle <span class=\"kw-bio\">LH/FSH</span>). <em>Signe le <span class=\"kw-def\">début de la puberté féminine</span>.</em></td>\n            <td><span class=\"kw-chiffre\">8-13 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Pubarche</strong></td>\n            <td>Apparition de la <span class=\"kw-clinique\">pilosité pubienne</span> (chez la fille comme chez le garçon). Liée à la production d'<span class=\"kw-bio\">androgènes</span> gonadiques et surrénaliens.</td>\n            <td>≈ <span class=\"kw-chiffre\">10-12 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Ménarche</strong></td>\n            <td>Survenue des <span class=\"kw-clinique\">premières règles</span> chez la fille — environ <span class=\"kw-chiffre\">2 ans</span> après la thélarche.</td>\n            <td>≈ <span class=\"kw-chiffre\">12,5 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À ne pas confondre :</strong>\n        <ul>\n          <li><span class=\"kw-def\">Adrénarche</span> = activation des <span class=\"kw-bio\">androgènes surrénaliens</span> (≈ <span class=\"kw-chiffre\">8 ans</span>) — physiologique, <strong>indépendante de l'axe gonadotrope</strong>.</li>\n          <li><span class=\"kw-def\">Gonadarche</span> = réactivation de l'<span class=\"kw-def\">axe hypothalamo-hypophyso-gonadique</span> (pulsatilité <span class=\"kw-bio\">GnRH</span>) — événement déclencheur de la puberté.</li>\n        </ul>\n      </div>","frequence":0},{"id":"49-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la valeur moyenne de la croissance pubertaire","contenu":"<table >\n        <thead><tr><th>Sexe</th><th>Vitesse de croissance pubertaire</th><th>Survenue (<span class=\"kw-def\">stade</span> Tanner)</th><th>Taille adulte moyenne</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fille 👧🏻</strong></td>\n            <td><span class=\"kw-chiffre\">+8 à 10 cm/an</span></td>\n            <td>Dès <span class=\"kw-clinique\">les</span> <strong>1ers signes pubertaires</strong> (<span class=\"kw-chiffre\">S2</span>)</td>\n            <td><span class=\"kw-chiffre\">≈ 1m65</span> (vers <span class=\"kw-chiffre\">16 ans</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Garçon 👦🏻</strong></td>\n            <td><span class=\"kw-chiffre\">+8 à 10 cm/an</span></td>\n            <td>Décalée, vers <strong><span class=\"kw-chiffre\">G3</span></strong></td>\n            <td><span class=\"kw-chiffre\">≈ 1m77</span> (vers <span class=\"kw-chiffre\">18 ans</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Mécanisme :</strong> <span class=\"kw-clinique\">les</span> pics de <span class=\"kw-bio\">GH</span> sont plus fréquents et amples, secondaires à l'augmentation systémique des <span class=\"kw-bio\">hormones sexuelles</span>. La <span class=\"kw-def\">fusion progressive des cartilages de croissance</span> ralentit puis stoppe la croissance (<em>indépendamment de la GH</em>).\n      </div>","frequence":0},{"id":"49-4","rang":"B","rubrique":"Définition","titre":"Connaître les différents stades de Tanner","contenu":"<p><span class=\"kw-def\">Classification</span> de <span class=\"kw-def\">Tanner</span> : <span class=\"kw-chiffre\">5 stades</span> (<span class=\"kw-chiffre\">1</span> = prépubère → <span class=\"kw-chiffre\">5</span> = adulte). Le <strong><span class=\"kw-def\">stade</span> 0 n'existe pas</strong>. Évalue 3 axes : <strong>S</strong> (seins), <strong>G</strong> (OGE masculins), <strong>P</strong> (pilosité pubienne).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Développement mammaire — fille (S)</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>S1</strong></td><td>Absence de <span class=\"kw-clinique\">développement mammaire</span></td></tr>\n          <tr><td><strong>S2</strong></td><td>Petit <span class=\"kw-clinique\">bourgeon mammaire</span> + élargissement de l'aréole</td></tr>\n          <tr><td><strong>S3</strong></td><td><span class=\"kw-clinique\">Glande mammaire</span> dépassant la surface de l'aréole</td></tr>\n          <tr><td><strong>S4</strong></td><td>Saillie aréole + mamelon sur la glande, sillon sous-mammaire</td></tr>\n          <tr><td><strong>S5</strong></td><td>Aspect adulte</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">OGE — garçon (G) · <em>orchidomètre de Prader</em></h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Volume testiculaire</th><th>Longueur testiculaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>G1</strong></td><td><span class=\"kw-chiffre\">&lt; 4 mL</span> (infantile)</td><td><span class=\"kw-chiffre\">&lt; 2,5 cm</span></td></tr>\n          <tr><td><strong>G2</strong></td><td><span class=\"kw-chiffre\">4-6 mL</span></td><td><span class=\"kw-chiffre\">2,5-3,0 cm</span></td></tr>\n          <tr><td><strong>G3</strong></td><td><span class=\"kw-chiffre\">8-10 mL</span></td><td><span class=\"kw-chiffre\">3,1-4,0 cm</span></td></tr>\n          <tr><td><strong>G4</strong></td><td><span class=\"kw-chiffre\">12-15 mL</span></td><td><span class=\"kw-chiffre\">4,1-4,5 cm</span></td></tr>\n          <tr><td><strong>G5</strong></td><td><span class=\"kw-chiffre\">20-25 mL</span> (adulte)</td><td><span class=\"kw-chiffre\">&gt; 4,5 cm</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pilosité pubienne (P)</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>P1</strong></td><td>Absence de <span class=\"kw-clinique\">pilosité</span></td></tr>\n          <tr><td><strong>P2</strong></td><td>Quelques poils sur le pubis</td></tr>\n          <tr><td><strong>P3</strong></td><td>Pilosité au-dessus de la symphyse</td></tr>\n          <tr><td><strong>P4</strong></td><td>Triangulaire, sans atteindre la racine des cuisses</td></tr>\n          <tr><td><strong>P5</strong></td><td>Adulte : triangulaire (♀) ou losangique étendu aux cuisses (♂)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Hors <span class=\"kw-def\">classification</span> :</strong> <span class=\"kw-clinique\">pilosité axillaire</span> (A) cotée <span class=\"kw-chiffre\">1-3</span>, peu d'intérêt clinique.\n      </div>","frequence":1,"liens":[{"href":"https://fr.wikipedia.org/wiki/Classification_de_Tanner","label":"Wikipedia — Classification de Tanner"}]},{"id":"49-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l'âge moyen de survenue de pic de croissance osseuse","contenu":"<ul>\n        <li><strong>Fille</strong> : pic de croissance pubertaire dès <strong><span class=\"kw-chiffre\">S2</span></strong> (souvent <span class=\"kw-chiffre\">11-12 ans</span>) ;</li>\n        <li><strong>Garçon</strong> : pic de croissance pubertaire plus tardif, vers <strong><span class=\"kw-chiffre\">G3</span></strong> (souvent <span class=\"kw-chiffre\">13-14 ans</span>) ;</li>\n        <li><span class=\"kw-def\">Masse osseuse maximale</span> atteinte vers <span class=\"kw-chiffre\">20 ans</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Maturation osseuse — <span class=\"kw-imagerie\">RX main gauche + poignet de face</span> (méthode <span class=\"kw-def\">Greulich-Pyle</span>)</h4>\n      <table >\n        <thead><tr><th>Repère</th><th>Fille</th><th>Garçon</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Apparition du <span class=\"kw-radio\">sésamoïde du pouce</span></strong></td>\n            <td><span class=\"kw-imagerie\">Âge osseux</span> <span class=\"kw-chiffre\">11 ans</span></td>\n            <td><span class=\"kw-imagerie\">Âge osseux</span> <span class=\"kw-chiffre\">13 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signification</strong></td>\n            <td colspan=\"2\">Contemporain du démarrage pubertaire — <strong><span class=\"kw-alerte\">impubérisme toujours anormal si l'âge osseux dépasse ces valeurs</span></strong>.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"49-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes physiologiques de la puberté masculine et féminine","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cascade hormonale du déclenchement</h4>\n      <ol>\n        <li><span class=\"kw-def\">Axe gonadotrope</span> fonctionnel <em>in utero</em> et quelques semaines après la naissance (« <span class=\"kw-def\">mini-puberté</span> ») ;</li>\n        <li><strong>Inhibition</strong> de l'axe pendant l'enfance ;</li>\n        <li><strong>Réactivation de la sécrétion pulsatile hypothalamique de <span class=\"kw-bio\">GnRH</span></strong> = déclenchement de la puberté ;</li>\n        <li>La GnRH stimule la sécrétion antéhypophysaire des <strong>gonadotrophines <span class=\"kw-bio\">FSH</span> et <span class=\"kw-bio\">LH</span></strong> ;</li>\n        <li>FSH et LH stimulent <span class=\"kw-clinique\">les</span> gonades → production des <span class=\"kw-bio\">stéroïdes sexuels</span>.</li>\n      </ol>\n\n      <table >\n        <thead><tr><th></th><th>Fille 👧🏻</th><th>Garçon 👦🏻</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Effecteurs gonadiques</strong></td>\n            <td>Activation ovarienne sous <span class=\"kw-bio\">LH/FSH</span> → <span class=\"kw-bio\">œstrogènes</span> ovariens</td>\n            <td><span class=\"kw-bio\">FSH</span> → développement <strong><span class=\"kw-clinique\">volume testiculaire</span></strong> · <span class=\"kw-bio\">LH</span> → production de <span class=\"kw-bio\">testostérone</span></td>\n          </tr>\n          <tr>\n            <td><strong>Conséquences cliniques</strong></td>\n            <td><span class=\"kw-clinique\">Développement mammaire</span>, utérovaginal, OGE, <span class=\"kw-clinique\">ménarche</span></td>\n            <td><span class=\"kw-clinique\">Verge</span>, pilosité, <span class=\"kw-clinique\">masse</span> musculaire, <span class=\"kw-clinique\">mue de la voix</span></td>\n          </tr>\n          <tr>\n            <td><strong>Marqueurs cliniques précoces</strong></td>\n            <td><span class=\"kw-clinique\">Thélarche</span> · pubarche · vulve horizontale · <span class=\"kw-clinique\">leucorrhées</span></td>\n            <td>↑ <span class=\"kw-clinique\">volume testiculaire</span> <span class=\"kw-chiffre\">≥ 4 mL</span> · pubarche · ↑ verge <span class=\"kw-chiffre\">≥ 6 cm</span> · <span class=\"kw-clinique\">gynécomastie</span> transitoire modérée fréquente</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pilosité :</strong> le développement pileux est secondaire à la production d'<span class=\"kw-bio\">androgènes gonadiques</span> <em>et</em> surrénaliens (adrénarche).\n      </div>","frequence":0},{"id":"49-7","rang":"B","rubrique":"Physiopathologie","titre":"Citer les deux facteurs susceptibles d'influencer la puberté (génétique et environnement)","contenu":"<p>L'apparition de la <span class=\"kw-def\">pulsatilité GnRH</span> est modulée par des facteurs neuroendocriniens et périphériques :</p>\n\n      <table >\n        <thead><tr><th>Facteur</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Génétiques</strong></td>\n            <td>Corrélation forte entre l'<strong>âge de la puberté des parents</strong> et celui des enfants — intérêt de l'interrogatoire familial.</td>\n          </tr>\n          <tr>\n            <td><strong>Ethniques</strong></td>\n            <td>Puberté un peu plus précoce chez <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-etio\">filles d'origine africaine</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>État nutritionnel</strong></td>\n            <td>Médié par la <span class=\"kw-def\">leptine</span> (hormone du tissu adipeux, proportionnelle à la <span class=\"kw-clinique\">masse</span> grasse) qui contribue à l'activation de l'<span class=\"kw-def\">axe gonadotrope</span>. <em><span class=\"kw-etio\">Obésité</span> → puberté plus précoce ; <span class=\"kw-etio\">dénutrition</span> / sport intensif → retard pubertaire.</em></td>\n          </tr>\n          <tr>\n            <td><strong>Pathologies intercurrentes</strong></td>\n            <td>Maladies chroniques (<span class=\"kw-etio\">cœliaque</span>, <span class=\"kw-etio\">MICI</span>, <span class=\"kw-etio\">IRC</span>) → retard pubertaire.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"49-8","rang":"B","rubrique":"Physiopathologie","titre":"Citer des exemples qui illustrent l'influence des facteurs génétiques et environnementaux sur la puberté","contenu":"<ul>\n        <li><strong>Exemple <span class=\"kw-etio\">génétique</span></strong> : enfants dont <span class=\"kw-clinique\">les</span> parents ont eu une puberté précoce ont eux-mêmes plus de risque de <span class=\"kw-clinique\">puberté précoce</span> (héritabilité forte de l'âge de ménarche).</li>\n        <li><strong>Exemple ethnique</strong> : <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-etio\">filles d'origine africaine</span></strong> ont une puberté en moyenne plus précoce que la population générale.</li>\n        <li><strong>Exemple nutritionnel / environnemental</strong> :\n          <ul>\n            <li>Enfants <strong><span class=\"kw-etio\">obèses</span></strong> → puberté plus précoce (effet <span class=\"kw-def\">leptine</span>) ;</li>\n            <li><strong><span class=\"kw-etio\">Dénutrition</span></strong>, <span class=\"kw-etio\">anorexie mentale</span>, sport intensif (gymnastes, danseuses) → retard pubertaire ;</li>\n            <li><strong><span class=\"kw-etio\">Perturbateurs endocriniens</span></strong> (suspectés) → potentiellement favorisant <span class=\"kw-clinique\">les</span> pubertés précoces.</li>\n          </ul>\n        </li>\n      </ul>","frequence":0},{"id":"49-9","rang":"A","rubrique":"Définition","titre":"Définir la puberté précoce et la puberté avancée","contenu":"<table >\n        <thead><tr><th></th><th>Puberté précoce</th><th>Puberté avancée</th><th>Puberté tardive</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fille</strong></td>\n            <td><span class=\"kw-clinique\">Développement mammaire</span> <span class=\"kw-alerte\">avant 8 ans</span></td>\n            <td>Entre <span class=\"kw-chiffre\">8-10 ans</span> — <em>non pathologique</em></td>\n            <td>Absence de développement mammaire <span class=\"kw-alerte\">après 13 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Garçon</strong></td>\n            <td><span class=\"kw-clinique\">Développement testiculaire</span> <span class=\"kw-alerte\">avant 9 ans</span> (peut être unilatéral)</td>\n            <td>Entre <span class=\"kw-chiffre\">9-11 ans</span> — <em>non pathologique</em></td>\n            <td>Absence de développement testiculaire <span class=\"kw-alerte\">après 14 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Bases statistiques :</strong> <span class=\"kw-clinique\">les</span> âges-limites sont définis statistiquement (<span class=\"kw-chiffre\">–2 DS</span> à <span class=\"kw-chiffre\">+2 DS</span>, soit <span class=\"kw-chiffre\">95 %</span> de la population). Hors de ces limites → probabilité de pathologie accrue. <em>Les différences ethniques (notamment puberté plus précoce chez les filles d'origine africaine) ne sont pas prises en compte dans ces définitions.</em>\n      </div>\n\n      <p><strong>Puberté tardive — autre critère :</strong> absence d'achèvement de la puberté <span class=\"kw-chiffre\">4 ans</span> après son début.</p>","frequence":0},{"id":"49-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les données de l'interrogatoire et de l'examen clinique orientant vers une puberté précoce","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Interrogatoire ciblé</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Antécédents familiaux</span></strong> :\n          <ul>\n            <li>Âges de début pubertaire des parents et de la fratrie ;</li>\n            <li>Âge de <span class=\"kw-clinique\">ménarche</span> chez la mère ;</li>\n            <li>Tailles des parents → <strong>calcul de la taille cible <span class=\"kw-etio\">génétique</span></strong> ;</li>\n            <li>ATCD familial de <strong><span class=\"kw-etio\">neurofibromatose de type 1 (NF1)</span></strong>.</li>\n          </ul>\n        </li>\n        <li><strong>Antécédents personnels</strong> : <span class=\"kw-etio\">NF1</span>, <span class=\"kw-etio\">méningite</span>, <span class=\"kw-etio\">traumatisme crânien</span>, <span class=\"kw-etio\">radiothérapie</span> ;</li>\n        <li><strong>Symptômes associés</strong> : <span class=\"kw-clinique\">signes visuels</span>, <span class=\"kw-alerte\">signes d'HTIC</span>, signes d'atteintes hypothalamo-hypophysaires.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen physique</h4>\n      <ul>\n        <li><strong>Cotation du <span class=\"kw-def\">stade</span> pubertaire</strong> (<span class=\"kw-def\">classification</span> de <span class=\"kw-def\">Tanner</span> — S, G, P) ;</li>\n        <li><span class=\"kw-clinique\">Taches cutanées</span> : café-au-lait (<span class=\"kw-etio\">NF1</span>, <span class=\"kw-etio\">McCune-Albright</span>) ;</li>\n        <li><strong>Accélération de la vitesse de croissance staturale</strong> (<span class=\"kw-chiffre\">&gt; 9 cm/an</span>) ;</li>\n        <li><span class=\"kw-clinique\">Signes d'hyperandrogénie</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Particularités épidémio :</strong> enfants <span class=\"kw-etio\">obèses</span> et enfants d'origine africaine ont une puberté plus précoce que la population générale.\n      </div>","frequence":0},{"id":"49-11","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir interpréter une courbe de croissance","contenu":"<p>La <span class=\"kw-def\">courbe de croissance</span> est l'outil-pivot du diagnostic pubertaire. Trois informations essentielles :</p>\n\n      <table >\n        <thead><tr><th>Paramètre</th><th>Puberté précoce</th><th>Puberté tardive</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Vitesse de croissance</strong></td>\n            <td><strong>Accélération</strong> : <span class=\"kw-alerte\">&gt; 9 cm/an</span></td>\n            <td>Reste celle de l'enfance — pas de pic pubertaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span> statural</strong></td>\n            <td><span class=\"kw-alerte\">Risque de petite taille définitive</span> (fusion précoce des cartilages de croissance)</td>\n            <td><span class=\"kw-alerte\">Risque de petite taille définitive</span> (pas de pic de croissance)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Âge osseux</span> (RX poignet)</strong></td>\n            <td><strong>Avance</strong> de l'âge osseux</td>\n            <td><strong>Retard</strong> de l'âge osseux par rapport à l'âge civil</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Méthode de lecture :</strong>\n        <ul>\n          <li>Suivre la <strong>position</strong> (couloir <span class=\"kw-chiffre\">DS</span>) et la <strong>pente</strong> (vitesse) ;</li>\n          <li>Comparer à la <strong>taille cible <span class=\"kw-etio\">génétique</span></strong> = (taille père + taille mère) / 2, <span class=\"kw-chiffre\">± 6,5 cm</span> selon le sexe ;</li>\n          <li>Rechercher une <strong><span class=\"kw-alerte\">cassure</span></strong> de la courbe (puberté pathologique, cause endocrinienne ou organique).</li>\n        </ul>\n      </div>","frequence":1},{"id":"49-12","rang":"B","rubrique":"Épidémiologie","titre":"Connaître l'épidémiologie de la puberté précoce","contenu":"<table >\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sex-ratio</strong></td>\n            <td>Pubertés précoces centrales <span class=\"kw-chiffre\">10× plus fréquentes chez la fille</span></td>\n          </tr>\n          <tr>\n            <td><strong>Étiologie dominante chez la fille</strong></td>\n            <td><span class=\"kw-etio\">Idiopathique</span> dans la majorité des cas (<span class=\"kw-imagerie\">IRM</span> normale)</td>\n          </tr>\n          <tr>\n            <td><strong>Étiologie dominante chez le garçon</strong></td>\n            <td>Beaucoup plus souvent reliée à une <span class=\"kw-alerte\">lésion intracrânienne (tumeur ⚠️)</span> — <span class=\"kw-imagerie\">IRM</span> impérative</td>\n          </tr>\n          <tr>\n            <td><strong>Pubertés précoces périphériques</strong></td>\n            <td>Très rares dans <span class=\"kw-clinique\">les</span> deux sexes</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs favorisants</strong></td>\n            <td><span class=\"kw-etio\">Obésité</span>, <span class=\"kw-etio\">origine africaine</span>, suspicion de <span class=\"kw-etio\">perturbateurs endocriniens</span></td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"49-13","rang":"B","rubrique":"Étiologies","titre":"Connaître les grands cadres étiologiques des pubertés précoces : origines hypothalamo-hypophysaire, ovariennes, surrénaliennes ou exogènes/environnementales","contenu":"<table >\n        <thead><tr><th></th><th>Puberté précoce centrale (la plus fréquente)</th><th>Puberté précoce périphérique (« pseudo-puberté »)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Réactivation prématurée de l'<span class=\"kw-def\">axe hypothalamo-hypophyso-gonadique</span> (lésionnelle ou non)</td>\n            <td>Sécrétion de <span class=\"kw-bio\">stéroïdes sexuels</span> d'origine <strong>gonadique</strong> ou surrénalienne, <strong>indépendante</strong> de l'axe HH</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Test au LH-RH</span></strong></td>\n            <td>Pic de <strong><span class=\"kw-bio\">LH</span> élevé</strong> (&gt; pic <span class=\"kw-bio\">FSH</span>)</td>\n            <td><span class=\"kw-bio\">Gonadotrophines</span> <strong>indétectables</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Grands cadres</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Tumeurs HH</span> (hamartome, gliome chiasmatique, astrocytome, germinome) ;</li>\n                <li>Non-tumorales : <span class=\"kw-etio\">hydrocéphalie</span>, kyste arachnoïdien, <span class=\"kw-etio\">trauma crânien</span>, <span class=\"kw-ttt\">radiothérapie</span> cérébrale ;</li>\n                <li><strong><span class=\"kw-etio\">Idiopathique</span></strong> (++ chez la fille).</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><strong>Ovariennes</strong> : <span class=\"kw-etio\">McCune-Albright</span>, kyste ovarien bénin, tumeur granulosa ;</li>\n                <li><strong>Testiculaires</strong> : <span class=\"kw-etio\">testotoxicose</span>, tumeur sécrétant hCG ;</li>\n                <li><strong>Surrénaliennes</strong> : <span class=\"kw-etio\">bloc 21-hydroxylase</span>, tumeur ;</li>\n                <li><strong>Exogènes</strong> : œstrogènes (fille), androgènes (garçon), perturbateurs endocriniens.</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"49-14","rang":"B","rubrique":"Étiologies","titre":"Connaître les étiologies précises des pubertés précoces","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pubertés précoces centrales</h4>\n      <table >\n        <thead><tr><th>Origine</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>HH <span class=\"kw-etio\">tumorale</span></strong></td>\n            <td><span class=\"kw-etio\">Hamartome hypothalamique</span> · <span class=\"kw-etio\">gliome du chiasma</span> (NF1 ou non) · <span class=\"kw-etio\">astrocytome</span> · <span class=\"kw-etio\">germinome</span> · kyste arachnoïdien</td>\n          </tr>\n          <tr>\n            <td><strong>HH non <span class=\"kw-etio\">tumorale</span></strong></td>\n            <td><span class=\"kw-etio\">Hydrocéphalie congénitale</span> · <span class=\"kw-etio\">trauma crânien</span> · ATCD <span class=\"kw-ttt\">radiothérapie</span> cérébrale · <span class=\"kw-etio\">méningite</span>/<span class=\"kw-etio\">encéphalite</span> séquellaires · <span class=\"kw-etio\">idiopathique +++</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pubertés précoces périphériques</h4>\n      <table >\n        <thead><tr><th>Origine</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Ovarienne</strong> (rare)</td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-etio\">Syndrome de McCune-Albright</span></strong> : <span class=\"kw-clinique\">taches café-au-lait</span> + <span class=\"kw-clinique\">dysplasie fibreuse osseuse</span> + puberté précoce (mutation somatique <em>GNAS</em>) ;</li>\n                <li><span class=\"kw-etio\">Kyste ovarien bénin</span> ;</li>\n                <li><span class=\"kw-etio\">Tumeur des cellules de la granulosa</span>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Testiculaire</strong> (rare)</td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-etio\">Testotoxicose</span></strong> : mutation activatrice du récepteur de la <span class=\"kw-bio\">LH</span> ;</li>\n                <li><span class=\"kw-etio\">Tumeur testiculaire sécrétant de l'hCG</span>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Surrénalienne</strong></td>\n            <td><span class=\"kw-etio\">Bloc en 21-hydroxylase</span> chez la fille · <span class=\"kw-etio\">tumeur surrénalienne</span></td>\n          </tr>\n          <tr>\n            <td><strong>Exogène</strong></td>\n            <td>Prise d'<span class=\"kw-bio\">œstrogènes</span> (fille) · <span class=\"kw-bio\">androgènes</span> (garçon) · <span class=\"kw-etio\">perturbateurs endocriniens</span> (suspectés)</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"49-15","rang":"B","rubrique":"Étiologies","titre":"Connaître le bilan biologique à prescrire en cas de puberté précoce avérée","contenu":"<table >\n        <thead><tr><th>Dosage</th><th>Indication / interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Inhibine B</span></strong></td>\n            <td><strong>Augmentée</strong> au cours de la puberté (rétrocontrôle négatif sur <span class=\"kw-bio\">FSH</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Test au LH-RH</span></strong> (gonadotrophines après stimulation)</td>\n            <td>\n              <ul>\n                <li><strong>Cause centrale</strong> : pic <span class=\"kw-alerte\">LH élevé &gt; pic FSH</span> ;</li>\n                <li><strong>Cause périphérique</strong> : <span class=\"kw-bio\">gonadotrophines</span> <span class=\"kw-alerte\">indétectables</span>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Testostérone</span></strong> (garçon)</td>\n            <td>Reflet de l'activation gonadique chez le garçon.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Œstradiol</span></strong> (fille)</td>\n            <td>Peu utile : variations fortes, la thélarche signe déjà la sécrétion œstrogénique. <em>(À doser selon le collège de gynéco.)</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Dosages complémentaires selon orientation :</strong> <span class=\"kw-bio\">17-OH-progestérone</span> (bloc 21-hydroxylase), <span class=\"kw-bio\">β-hCG</span> (tumeur sécrétante), <span class=\"kw-bio\">DHEAS</span> / <span class=\"kw-bio\">Δ4-androstènedione</span> (orientation surrénalienne).\n      </div>","frequence":0},{"id":"49-16","rang":"A","rubrique":"Diagnostic positif","titre":"Définir le retard pubertaire du garçon et de la fille","contenu":"<table >\n        <thead><tr><th>Sexe</th><th>Définition du retard pubertaire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fille 👧🏻</strong></td>\n            <td>Absence de <span class=\"kw-clinique\">développement mammaire</span> <span class=\"kw-alerte\">après 13 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Garçon 👦🏻</strong></td>\n            <td>Absence de <span class=\"kw-clinique\">développement testiculaire</span> <span class=\"kw-alerte\">après 14 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Critère commun</strong></td>\n            <td>Absence d'achèvement de la puberté <span class=\"kw-chiffre\">4 ans</span> après son début</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Vitesse de croissance</strong> dans le retard pubertaire : reste celle de l'enfance, sans pic pubertaire — d'où le <strong><span class=\"kw-alerte\">risque de petite taille définitive</span></strong>.</p>","frequence":0},{"id":"49-17","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les données de l'interrogatoire et de l'examen clinique en faveur d'un retard pubertaire","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Interrogatoire</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Antécédents familiaux</span></strong> :\n          <ul>\n            <li>Âges de début pubertaire des parents et de la fratrie ;</li>\n            <li>Âge de <span class=\"kw-clinique\">ménarche</span> chez la mère ;</li>\n            <li>Tailles des parents (taille cible <span class=\"kw-etio\">génétique</span>) ;</li>\n            <li><span class=\"kw-etio\">Infertilité familiale</span> ;</li>\n            <li><span class=\"kw-clinique\">Troubles de l'odorat</span> associés ou non à un trouble pubertaire (<span class=\"kw-etio\">Kallmann</span>).</li>\n          </ul>\n        </li>\n        <li><strong>Antécédents personnels</strong> :\n          <ul>\n            <li>Ralentissement de la croissance ;</li>\n            <li>Maladies chroniques (<span class=\"kw-etio\">cœliaque</span>, <span class=\"kw-etio\">MICI</span>, <span class=\"kw-etio\">IRC</span>) ;</li>\n            <li><strong><span class=\"kw-etio\">Cryptorchidie</span></strong> chez le garçon (notamment bilatérale).</li>\n          </ul>\n        </li>\n        <li><strong>Symptômes associés</strong> :\n          <ul>\n            <li><span class=\"kw-clinique\">Signes visuels</span>, <span class=\"kw-alerte\">signes d'HTIC</span> ;</li>\n            <li>Signes d'autres atteintes hypothalamo-hypophysaires ;</li>\n            <li><strong><span class=\"kw-clinique\">Anosmie / hyposmie</span></strong> → <span class=\"kw-etio\">syndrome de Kallmann</span> ;</li>\n            <li>Signes digestifs (<span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">douleurs abdominales</span>) → <span class=\"kw-etio\">maladie cœliaque</span>, <span class=\"kw-etio\">MICI</span>.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen physique</h4>\n      <ul>\n        <li>Cotation du <strong><span class=\"kw-def\">stade</span> pubertaire</strong> (<span class=\"kw-def\">Tanner</span>) ;</li>\n        <li><strong><span class=\"kw-clinique\">Syndrome dysmorphique</span></strong> (<span class=\"kw-etio\">Turner</span>, <span class=\"kw-etio\">Klinefelter</span>) ;</li>\n        <li>Examen des <strong>OGE</strong> : <span class=\"kw-clinique\">cryptorchidie</span>, <span class=\"kw-clinique\">micropénis</span> ;</li>\n        <li><strong>État nutritionnel</strong> (dénutrition, <span class=\"kw-clinique\">anorexie</span>) ;</li>\n        <li>Examen complet, en particulier <strong>neurologique</strong>.</li>\n      </ul>","frequence":1},{"id":"49-18","rang":"B","rubrique":"Étiologies","titre":"Connaître le bilan biologique à prescrire en cas de retard pubertaire","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Dosages hormonaux</h4>\n      <table >\n        <thead><tr><th>Hormone</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Stéroïdes sexuels</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-bio\">Testostérone</span></strong> chez le garçon : basse traduisant l'absence de puberté ;</li>\n                <li><strong><span class=\"kw-bio\">Œstradiol</span></strong> chez la fille : peu utile (variations fortes).</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">FSH / LH (basaux)</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Élevées</strong> → cause <strong>périphérique</strong> ;</li>\n                <li><strong>Basses</strong> → cause <strong>centrale</strong> <em>(mais aussi retard pubertaire simple !)</em>.</li>\n              </ul>\n              <span class=\"kw-alerte\">⚠️ Contrairement à la puberté précoce, les FSH/LH sont dosées à l'état basal et non après stimulation.</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres hormones AH</strong></td>\n            <td>Si insuffisance antéhypophysaire évoquée (cassure staturale, autres axes) : <strong><span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">T4L</span>, <span class=\"kw-bio\">IGF-1</span>, <span class=\"kw-bio\">cortisol</span>, <span class=\"kw-bio\">prolactine</span></strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Autres examens complémentaires</h4>\n      <ul>\n        <li><strong>Systématiquement</strong> :\n          <ul>\n            <li><span class=\"kw-bio\">Ionogramme sanguin</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span> ;</li>\n            <li><strong><span class=\"kw-bio\">IgA anti-transglutaminase</span> + <span class=\"kw-bio\">IgA totales</span></strong> (<span class=\"kw-def\">dépistage</span> <span class=\"kw-etio\">maladie cœliaque</span>) ;</li>\n            <li><strong><span class=\"kw-imagerie\">RX main gauche + poignet</span></strong> (âge osseux).</li>\n          </ul>\n        </li>\n        <li><strong>Selon l'orientation</strong> :\n          <ul>\n            <li>Si hypogonadisme <strong>hyper</strong>gonadotrope → <strong><span class=\"kw-bio\">caryotype</span></strong> ;</li>\n            <li>Si hypogonadisme <strong>hypo</strong>gonadotrope → <strong><span class=\"kw-imagerie\">IRM</span> hypothalamo-hypophysaire</strong>.</li>\n          </ul>\n        </li>\n      </ul>","frequence":1},{"id":"49-19","rang":"A","rubrique":"Étiologies","titre":"Connaître les 2 grands cadres étiologiques des retards pubertaires : origines hypothalamo-hypophysaire ou gonadique","contenu":"<table >\n        <thead><tr><th></th><th>Retard pubertaire central (hypogonadisme hypogonadotrope)</th><th>Retard pubertaire périphérique (hypogonadisme hypergonadotrope)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Atteinte hypothalamo-hypophysaire → <span class=\"kw-bio\">FSH/LH</span> <strong>basses</strong></td>\n            <td>Atteinte primitive des gonades → <span class=\"kw-bio\">FSH/LH</span> <strong>élevées</strong> (rétrocontrôle négatif perdu)</td>\n          </tr>\n          <tr>\n            <td><strong>Causes acquises</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-etio\">Tumeur HH</span></strong> (craniopharyngiome, adénome) ;</li>\n                <li>Causes fonctionnelles : <span class=\"kw-etio\">dénutrition</span>, sport intensif, manque de sommeil, maladies chroniques.</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>ATCD <strong><span class=\"kw-etio\">chimiothérapie</span></strong> ou <strong><span class=\"kw-etio\">radiothérapie</span></strong> pelvienne ;</li>\n                <li><span class=\"kw-etio\">Insuffisance ovarienne auto-immune</span>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes constitutionnelles</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-etio\">Syndrome de Kallmann</span></strong> (+ <span class=\"kw-clinique\">anosmie/hyposmie</span>) ;</li>\n                <li>Hypogonadisme hypogonadotrope isolé sans trouble olfactif ;</li>\n                <li>Expression possible avec <span class=\"kw-clinique\">cryptorchidie bilatérale</span> et/ou <span class=\"kw-clinique\">micropénis</span>.</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-etio\">Syndrome de Turner</span></strong> (♀, <span class=\"kw-chiffre\">45,X</span> ou <span class=\"kw-chiffre\">45,X/46,XX</span>) ;</li>\n                <li><strong><span class=\"kw-etio\">Syndrome de Klinefelter</span></strong> (♂, <span class=\"kw-chiffre\">47,XXY</span>).</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen-clé</strong></td>\n            <td><span class=\"kw-alerte\">IRM cérébrale systématique</span></td>\n            <td><span class=\"kw-alerte\">Caryotype systématique</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Zoom — <span class=\"kw-clinique\">les</span> 2 causes gonadiques</strong> (<span class=\"kw-bio\">caryotype</span> systématique) :</p>\n      <p><strong><span class=\"kw-etio\">Syndrome de Turner</span></strong> <span class=\"kw-chiffre\">(♀ · 45,X ou mosaïque)</span></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Petite taille</span> + dysmorphie : <span class=\"kw-clinique\">cou palmé</span> (pterygium coli), <span class=\"kw-clinique\">cubitus valgus</span>, écartement mamelonnaire ;</li>\n        <li><span class=\"kw-clinique\">Insuffisance ovarienne</span> (absence de puberté, infertilité) ; <span class=\"kw-alerte\">coarctation de l'aorte / bicuspidie aortique</span> ;</li>\n        <li><span class=\"kw-bio\">Caryotype</span> systématique devant <strong>toute petite taille de la fille</strong>, même sans signe clinique.</li>\n      </ul>\n      <p><strong><span class=\"kw-etio\">Syndrome de Klinefelter</span></strong> <span class=\"kw-chiffre\">(♂ · 47,XXY · tombé en annale)</span></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Grande taille eunuchoïde</span> (membres longs), <span class=\"kw-clinique\">gynécomastie</span> fréquente ;</li>\n        <li>Signes pubertaires présents mais <span class=\"kw-clinique\">testicules petits</span> (<span class=\"kw-chiffre\">&lt; 35 mm</span>) → <span class=\"kw-alerte\">azoospermie</span>, infertilité.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Diagnostic d'élimination — retard pubertaire simple</strong> : axe HHG resté quiescent, activation gonadotrope retardée. Diagnostic <strong>le plus fréquent</strong> (surtout garçon) mais reste un <span class=\"kw-alerte\">diagnostic d'élimination</span>. ATCD familiaux fréquents, <span class=\"kw-imagerie\">âge osseux</span> retardé, <span class=\"kw-def\">pronostic</span> statural satisfaisant.\n      </div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/turner-syndrome","label":"Radiopaedia : Turner syndrome"},{"href":"https://radiopaedia.org/articles/klinefelter-syndrome","label":"Radiopaedia : Klinefelter syndrome"},{"href":"https://www.msdmanuals.com/fr/accueil/probl%C3%A8mes-de-sant%C3%A9-infantiles/anomalies-chromosomiques-et-g%C3%A9n%C3%A9tiques/syndrome-de-klinefelter","label":"MSD Manuals — Syndrome de Klinefelter"}]},{"id":"49-20","rang":"B","rubrique":"Contenu multimédia","titre":"Courbe de croissance précocité pubertaire","contenu":"<p>Courbe de croissance dans la <span class=\"kw-clinique\">puberté précoce</span> :</p>\n      <ul>\n        <li><strong>Accélération de la vitesse de croissance</strong> (<span class=\"kw-chiffre\">&gt; 9 cm/an</span>) — courbe qui « décroche vers le haut » ;</li>\n        <li><strong>Avance de l'<span class=\"kw-imagerie\">âge osseux</span></strong> sur l'âge civil ;</li>\n        <li><strong><span class=\"kw-alerte\">Risque de petite taille définitive</span></strong> à long terme (fusion précoce des cartilages de croissance).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Renvoi pédagogique :</strong> consulter <span class=\"kw-clinique\">les</span> courbes de croissance du carnet de santé + atlas <span class=\"kw-def\">Greulich-Pyle</span> pour visualisation.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/49/courbe-croissance-precocite-pubertaire.jpg\" alt=\"Courbe staturo-pondérale d'une fille : accélération de la vitesse de croissance décrochant vers le haut, suspicion de puberté précoce\" loading=\"lazy\">\n        <figcaption>Courbe staturo-pondérale (fille) — accélération de la vitesse de croissance « décrochant vers le haut » vers <span class=\"kw-chiffre\">7 ans</span>, suspicion de puberté précoce (patiente P2S2R0). Source : iconographie EDN / Collège de pédiatrie.</figcaption>\n      </figure>","frequence":0},{"id":"49-21","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies : prématuré thélarche","contenu":"<p><span class=\"kw-def\">Prémature thélarche</span> = développement précoce et isolé des <span class=\"kw-clinique\">seins</span>.</p>\n\n      <table >\n        <thead><tr><th>Critère</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cause</strong></td><td>Souvent physiologique avant l'âge de <span class=\"kw-chiffre\">&lt; 2 ans</span> (effet de la mini-puberté résiduelle).</td></tr>\n          <tr><td><strong>Diagnostic</strong></td><td><span class=\"kw-alerte\">Diagnostic d'élimination</span> — après avoir évoqué une puberté précoce vraie, notamment si survenue après l'âge de <span class=\"kw-chiffre\">&gt; 2 ans</span> 🚩.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>Pas d'<span class=\"kw-clinique\">évolution</span> clinique, bilan <span class=\"kw-bio\">biologique</span> + <span class=\"kw-imagerie\">échographique</span> négatifs.</td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/49/premature-thelarche.png\" alt=\"Prémature thélarche : développement mammaire précoce et isolé chez le nourrisson\" loading=\"lazy\">\n        <figcaption>Prémature thélarche — développement mammaire précoce et isolé, sans autre signe pubertaire associé. Source : iconographie EDN / Collège de pédiatrie.</figcaption>\n      </figure>","frequence":0},{"id":"49-22","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies : adrénarche","contenu":"<p><span class=\"kw-def\">Adrénarche</span> (= prémature pubarche) = <span class=\"kw-clinique\">pilosité pubienne précoce isolée</span>.</p>\n\n      <table >\n        <thead><tr><th>Critère</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cause</strong></td><td>Augmentation physiologique de la production des <span class=\"kw-bio\">androgènes surrénaliens</span> vers l'âge de <span class=\"kw-chiffre\">8 ans</span>. <strong>Indépendante des gonadotrophines</strong> — ce n'est <em>pas</em> un signe de puberté.</td></tr>\n          <tr>\n            <td><strong>Diagnostic</strong></td>\n            <td><span class=\"kw-alerte\">Diagnostic d'élimination</span> — écarter une production pathologique d'androgènes :\n              <ul>\n                <li><span class=\"kw-etio\">Tumeur surrénalienne</span> ;</li>\n                <li><span class=\"kw-etio\">Tumeur gonadique</span> ;</li>\n                <li><span class=\"kw-etio\">Hyperplasie congénitale des surrénales</span> à révélation tardive (bloc 21-OH).</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><em>Photographies de référence : cf. collège de pédiatrie / iconographie EDN. <!-- TODO Kevin : pas de planche item 49 dans IMAGERIE A CONNAITRE.pdf ; déposer une photo dans assets/images/49/ si dispo. --></em></p>","frequence":0},{"id":"49-23","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies : puberté précoce chez la fille","contenu":"<p>Reconnaissance clinique d'une <span class=\"kw-clinique\">puberté précoce centrale</span> chez la fille (<span class=\"kw-alerte\">&lt; 8 ans</span>) :</p>\n      <ul>\n        <li>Apparition d'un <strong><span class=\"kw-clinique\">bourgeon mammaire</span></strong> (S2) ;</li>\n        <li><strong><span class=\"kw-clinique\">Pubarche</span></strong> (P2-P3) ;</li>\n        <li>Modifications de la <strong><span class=\"kw-clinique\">vulve</span></strong> (verticale → horizontale, augmentation du volume des lèvres et du clitoris) ;</li>\n        <li><strong><span class=\"kw-clinique\">Leucorrhées</span></strong> physiologiques (muqueuses rosées et sécrétantes).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-alerte\">Corps étranger intra-vaginal</span> :</strong> principal <span class=\"kw-def\">diagnostic différentiel</span> chez une fille présentant des <span class=\"kw-clinique\">saignements</span> (penser aussi aux <span class=\"kw-alerte\">sévices sexuels</span>).\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/49/puberte-precoce-fille.jpg\" alt=\"Puberté précoce centrale chez une fille de 7 ans : développement mammaire stade S2\" loading=\"lazy\">\n        <figcaption>Puberté précoce centrale chez une fille — développement mammaire (<span class=\"kw-def\">stade</span> S2) à l'âge de <span class=\"kw-chiffre\">7 ans</span> (patiente P2S2R0). Source : iconographie EDN / Collège de pédiatrie.</figcaption>\n      </figure>","frequence":0},{"id":"49-24","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l'indication des examens d'imagerie devant une puberté anormale","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indication</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RX main gauche + poignet</span></strong> (face)</td>\n            <td><strong>Systématique</strong> dans toute puberté anormale</td>\n            <td>Appréciation de l'<strong><span class=\"kw-imagerie\">âge osseux</span></strong> (méthode de <span class=\"kw-def\">Greulich-Pyle</span>) — avance dans la PP, retard dans le retard pubertaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM hypothalamo-hypophysaire</span></strong></td>\n            <td>\n              <ul>\n                <li>Puberté précoce <strong>centrale</strong> ;</li>\n                <li>Retard pubertaire <strong>hypogonadotrope</strong>.</li>\n              </ul>\n            </td>\n            <td>Recherche de <strong><span class=\"kw-alerte\">tumeur HH</span></strong> (hamartome, gliome du chiasma, craniopharyngiome…), kyste arachnoïdien, malformations</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie pelvienne</span></strong></td>\n            <td>Fille : puberté précoce / retard pubertaire</td>\n            <td>\n              <ul>\n                <li>Élimination d'un <span class=\"kw-alerte\">processus tumoral</span> ;</li>\n                <li>Imprégnation œstrogénique : <span class=\"kw-radio\">ligne de vacuité</span> endomètre + L corps utérin <span class=\"kw-chiffre\">&gt; 35 mm</span>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie testiculaire</span></strong></td>\n            <td>Garçon : puberté précoce périphérique</td>\n            <td><span class=\"kw-etio\">Tumeur testiculaire sécrétant hCG</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Imagerie surrénalienne</span></strong></td>\n            <td>Si orientation surrénalienne (<span class=\"kw-bio\">DHEAS</span>, <span class=\"kw-bio\">17-OHP</span>)</td>\n            <td><span class=\"kw-etio\">Tumeur surrénalienne</span>, hyperplasie <span class=\"kw-etio\">congénitale</span></td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"49-25","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l'objectif de l'échographie pelvienne et de la radiographie de la main et du poignet dans une puberté pathologique","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RX main gauche + poignet</span></strong> (face)</td>\n            <td>\n              <ul>\n                <li>Évaluer l'<strong><span class=\"kw-imagerie\">âge osseux</span></strong> (<span class=\"kw-def\">Greulich-Pyle</span>) ;</li>\n                <li>Repérer le <strong><span class=\"kw-radio\">sésamoïde du pouce</span></strong> (apparition = démarrage pubertaire : <span class=\"kw-chiffre\">11 ans ♀</span> / <span class=\"kw-chiffre\">13 ans ♂</span>) ;</li>\n                <li>Comparer à l'âge civil → avance (PP) ou retard (retard pubertaire) ;</li>\n                <li>Évaluer le <strong><span class=\"kw-def\">pronostic</span> statural</strong>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie pelvienne</span></strong> (fille)</td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-alerte\">Éliminer un processus tumoral</span></strong> ovarien ou utérin ;</li>\n                <li><strong>Apprécier l'imprégnation œstrogénique</strong> :\n                  <ul>\n                    <li>Apparition d'une <strong><span class=\"kw-radio\">ligne de vacuité</span></strong> de l'endomètre ;</li>\n                    <li>Augmentation de la <strong>longueur du corps utérin (<span class=\"kw-chiffre\">&gt; 35 mm</span>)</strong>.</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"49-26","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les éléments d'interprétation d'un âge osseux sur une radiographie de poignet","contenu":"<p>Méthode de référence : <span class=\"kw-def\">Greulich et Pyle</span> sur <span class=\"kw-imagerie\">radiographie</span> de <strong>main gauche + poignet de face</strong>.</p>\n\n      <table >\n        <thead><tr><th>Élément</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-radio\">Sésamoïde du pouce</span></strong></td>\n            <td>\n              <ul>\n                <li>Apparition à <span class=\"kw-imagerie\">âge osseux</span> <span class=\"kw-chiffre\">11 ans (♀)</span> ou <span class=\"kw-chiffre\">13 ans (♂)</span> ;</li>\n                <li>Contemporain du démarrage pubertaire ;</li>\n                <li><strong><span class=\"kw-alerte\">Impubérisme toujours anormal si l'âge osseux dépasse ces valeurs</span></strong>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Noyaux d'ossification du carpe</strong></td>\n            <td>Apparition séquentielle des os du carpe — atlas de comparaison.</td>\n          </tr>\n          <tr>\n            <td><strong>Cartilages de conjugaison</strong></td>\n            <td>Fusion progressive → arrêt de la croissance.</td>\n          </tr>\n          <tr>\n            <td><strong>Comparaison âge osseux / âge civil</strong></td>\n            <td>\n              <ul>\n                <li><strong>AO &gt; âge civil</strong> → puberté précoce, hyperandrogénie, <span class=\"kw-etio\">obésité</span> ;</li>\n                <li><strong>AO &lt; âge civil</strong> → retard pubertaire (simple ou pathologique), <span class=\"kw-etio\">hypothyroïdie</span>, <span class=\"kw-etio\">dénutrition</span>, déficit en <span class=\"kw-bio\">GH</span>.</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU & Pièges » et « Stratégie & CAT » : à compléter après revue clinique.</p>"}],"strategie":{"redflags":"<ul><li><span class=\"kw-clinique\">Puberté précoce chez le garçon</span> → <span class=\"kw-alerte\">tumeur intracrânienne</span> à redouter → <span class=\"kw-imagerie\">IRM hypothalamo-hypophysaire</span> impérative</li><li><span class=\"kw-alerte\">Signes d'HTIC</span> ou <span class=\"kw-clinique\">signes visuels</span> → <span class=\"kw-etio\">tumeur hypothalamo-hypophysaire</span></li><li><span class=\"kw-clinique\">Accélération de la vitesse de croissance</span> <span class=\"kw-chiffre\">&gt; 9 cm/an</span> → puberté précoce</li><li><span class=\"kw-clinique\">Taches café-au-lait</span> → <span class=\"kw-etio\">NF1</span>, <span class=\"kw-etio\">syndrome de McCune-Albright</span></li><li><span class=\"kw-def\">Prémature thélarche</span> survenant <span class=\"kw-chiffre\">après 2 ans</span> → écarter une <span class=\"kw-alerte\">puberté précoce vraie</span> avant d'étiqueter</li><li><span class=\"kw-clinique\">Saignements</span> chez une petite fille → <span class=\"kw-alerte\">corps étranger intra-vaginal</span>, penser aux <span class=\"kw-alerte\">sévices sexuels</span></li><li><span class=\"kw-alerte\">Impubérisme toujours anormal</span> si l'<span class=\"kw-imagerie\">âge osseux</span> dépasse <span class=\"kw-chiffre\">11 ans (♀)</span> / <span class=\"kw-chiffre\">13 ans (♂)</span></li><li><span class=\"kw-clinique\">Cryptorchidie bilatérale</span> chez le garçon → exclut le <span class=\"kw-def\">retard pubertaire simple</span> (oriente vers une cause organique)</li></ul>","principes":"<p><strong>Démarche avant tout diagnostique</strong> : la conduite dépend de l'étiologie. Deux situations ont une PEC codifiée par <span class=\"kw-clinique\">les</span> sources — le <span class=\"kw-def\">retard pubertaire simple</span> (abstention + <span class=\"kw-def\">suivi</span>) et le <span class=\"kw-def\">syndrome de Turner</span> (correction de l'hypogonadisme).</p><p><strong><span class=\"kw-clinique\">Syndrome de Turner</span> <span class=\"q\">— correction de l'hypogonadisme</span></strong></p><p>Traitement fondé avant tout sur la <strong>correction de l'hypogonadisme</strong></p><ul><li><span class=\"kw-ttt\">Œstrogénisation</span> proposée dès que le diagnostic est posé</li><li><span class=\"kw-ttt\">Hormone de croissance (GH)</span> le plus souvent associée pour améliorer le <strong><span class=\"kw-def\">pronostic</span> statural</strong></li><li><span class=\"kw-ttt\">Traitement œstroprogestatif</span> poursuivi à l'âge adulte → prévention de la <span class=\"kw-alerte\">perte osseuse</span></li></ul><p><strong>Retard pubertaire simple <span class=\"q\">— diagnostic d'élimination</span></strong></p><p><span class=\"kw-alerte\">Diagnostic d'élimination</span> : une tumeur ou une maladie <span class=\"kw-etio\">inflammatoire</span> peut se présenter comme un retard simple</p><ul><li><strong><span class=\"kw-def\">Surveillance</span> clinique simple suffisante</strong> : <span class=\"kw-bio\">examens complémentaires inutiles</span></li><li>Conditions : <span class=\"kw-etio\">ATCD familiaux de puberté tardive</span>, examen normal, <span class=\"kw-imagerie\">âge osseux</span> retardé, taille <span class=\"kw-chiffre\">&gt; −2 DS</span></li></ul>","suivi":"<p><strong>Outil de <span class=\"kw-def\">suivi</span> : courbe de croissance</strong></p><ul><li>Suivre la <strong>vitesse de croissance</strong> et le couloir de taille (<span class=\"kw-chiffre\">DS</span>)</li><li>Comparer <span class=\"kw-imagerie\">âge osseux</span> et âge civil (avance → puberté précoce ; retard → retard pubertaire)</li></ul><p><strong>Retard pubertaire simple</strong></p><ul><li><strong>Suivre l'enfant jusqu'au démarrage de la puberté</strong></li><li><span class=\"kw-def\">Pronostic</span> <strong>bon</strong> sur <span class=\"kw-clinique\">les</span> plans pubertaire et statural</li></ul><p><strong><span class=\"kw-clinique\">Syndrome de Turner</span></strong></p><ul><li><span class=\"kw-def\">Surveillance</span> de la <span class=\"kw-bio\">densité minérale osseuse</span> (déficit accentué dès la puberté par l'hypogonadisme)</li><li><span class=\"kw-def\">Dépistage</span> du <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">auto-immun</span> : <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">hypothyroïdie</span>, <span class=\"kw-etio\">maladie cœliaque</span></li></ul><p><strong>Prémature thélarche / adrénarche</strong></p><ul><li>Pas d'<span class=\"kw-clinique\">évolution</span> clinique, bilan <span class=\"kw-bio\">biologique</span> + <span class=\"kw-imagerie\">échographique</span> négatifs</li><li>Simple <strong><span class=\"kw-def\">surveillance</span></strong> (diagnostic d'élimination)</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/croissance-developpement/puberte-normale-pathologique","label":"Collège Pédiatrie — Puberté normale et pathologique"}],"cards":[{"i":"127de10ff7db","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quelle spécificité concerne les cycles menstruels après la ménarche ?","a":"<p>L'<strong>irrégularité des cycles</strong> est normale durant les <strong>2 premières années</strong> post-ménarche, bien que les cycles soient généralement ovulatoires dès la première année.</p>"},{"i":"134f0ad4843a","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quelle est la durée moyenne de la puberté ?","a":"<p>La durée moyenne de la puberté est de <strong>4 ans</strong>.</p>"},{"i":"550baa697d7a","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quelle est l'hormone-clé de la puberté chez la fille ?","a":"<p>L'hormone-clé de la puberté chez la fille est les <strong>œstrogènes</strong>, dont la sécrétion est stimulée par la LH et la FSH.</p>"},{"i":"63014441f80f","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quel est le premier signe pubertaire chez le garçon et dans quelle tranche d'âge survient-il ?","a":"<p>Le premier signe pubertaire chez le garçon est l'<strong>augmentation du volume testiculaire</strong> (≥ 4 mL ou longueur ≥ 25 mm), qui survient normalement entre <strong>9 et 14 ans</strong>.</p>"},{"i":"7449796ffb77","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quel est le premier signe pubertaire chez la fille et dans quelle tranche d'âge survient-il ?","a":"<p>Le premier signe pubertaire chez la fille est la <strong>thélarche</strong> (développement du bourgeon mammaire), qui survient normalement entre <strong>8 et 13 ans</strong>.</p>"},{"i":"9e86f3ec89c5","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quelle est la définition de la puberté ?","a":"<p>La puberté est l'ensemble des phénomènes physiques, psychiques, mentaux et affectifs marquant la transition entre l'enfance et l'âge adulte.</p>"},{"i":"d5358094c04b","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quels sont les quatre phénomènes physiques caractérisant la puberté ?","a":"<ul><li>Acquisition des caractères sexuels secondaires.</li><li>Maturation de la fonction sécrétoire gonadique.</li><li>Acquisition des fonctions de reproduction.</li><li>Accélération de la vitesse de croissance staturale jusqu'à la taille définitive.</li></ul>"},{"i":"ef17a56e9fc8","n":49,"o":"49-1","u":"Évaluation","t":"Connaître le développement pubertaire normal","q":"Quelle est l'hormone-clé de la puberté chez le garçon ?","a":"<p>Les hormones-clés de la puberté chez le garçon sont la <strong>FSH</strong> (pour le volume testiculaire) puis la <strong>testostérone</strong> (sous l'action de la LH).</p>"},{"i":"1dda3d0b6e09","n":49,"o":"49-10","u":"Diagnostic positif","t":"Connaître les données de l'interrogatoire et de l'examen clinique orientant vers une puberté précoce","q":"Quels sont les éléments clés de l'interrogatoire orientant vers une puberté précoce concernant les antécédents personnels et les symptômes associés ?","a":"<p>Il faut rechercher des antécédents personnels de :</p><ul><li><strong>Neurofibromatose de type 1 (NF1)</strong>.</li><li><strong>Méningite</strong>.</li><li><strong>Traumatisme crânien</strong>.</li><li><strong>Radiothérapie</strong>.</ul><p>Les symptômes associés à rechercher sont :</p><ul><li>Des <strong>signes visuels</strong>.</li><li>Des <strong>signes d'hypertension intracrânienne (HTIC)</strong>.</li><li>Des <strong>signes d'atteintes hypothalamo-hypophysaires</strong>.</li></ul>"},{"i":"35aee0dae21d","n":49,"o":"49-10","u":"Diagnostic positif","t":"Connaître les données de l'interrogatoire et de l'examen clinique orientant vers une puberté précoce","q":"Quels sont les éléments clés de l'examen clinique orientant vers une puberté précoce ?","a":"<p>L'examen clinique doit inclure :</p><ul><li>La <strong>cotation du stade pubertaire</strong> selon la classification de Tanner (S pour seins, G pour organes génitaux, P pour pilosité).</li><li>La recherche de <strong>taches cutanées</strong>, notamment <strong>café-au-lait</strong>, orientant vers une NF1 ou un syndrome de McCune-Albright.</li><li>L'évaluation de la <strong>vitesse de croissance staturale</strong> : une accélération > 9 cm/an est suspecte.</li><li>La recherche de <strong>signes d'hyperandrogénie</strong>.</li></ul>"},{"i":"529577d7a474","n":49,"o":"49-10","u":"Diagnostic positif","t":"Connaître les données de l'interrogatoire et de l'examen clinique orientant vers une puberté précoce","q":"Quels sont les éléments clés de l'interrogatoire orientant vers une puberté précoce concernant les antécédents familiaux ?","a":"<p>Il faut rechercher :</p><ul><li>Les <strong>âges de début pubertaire</strong> des parents et de la fratrie.</li><li>L'<strong>âge de ménarche</strong> chez la mère.</li><li>Les <strong>tailles des parents</strong> pour le calcul de la taille cible génétique.</li><li>Un antécédent familial de <strong>neurofibromatose de type 1 (NF1)</strong>.</li></ul>"},{"i":"4396ff41f370","n":49,"o":"49-11","u":"Diagnostic positif","t":"Savoir interpréter une courbe de croissance","q":"Quelles informations essentielles une courbe de croissance doit-elle fournir pour l'évaluation de la puberté ?","a":"<ul><li>La <strong>vitesse de croissance</strong>.</li><li>Le <strong>pronostic statural</strong>.</li><li>L'<strong>âge osseux</strong> (par radiographie du poignet).</li></ul>"},{"i":"596d7d1d6fe0","n":49,"o":"49-11","u":"Diagnostic positif","t":"Savoir interpréter une courbe de croissance","q":"Comment l'âge osseux, évalué par radiographie du poignet, est-il interprété dans le cadre d'une puberté pathologique ?","a":"<ul><li>En cas de <strong>puberté précoce</strong>, on observe une <strong>avance de l'âge osseux</strong> par rapport à l'âge civil.</li><li>En cas de <strong>puberté tardive</strong>, on observe un <strong>retard de l'âge osseux</strong> par rapport à l'âge civil.</li></ul>"},{"i":"617e1aea3562","n":49,"o":"49-11","u":"Diagnostic positif","t":"Savoir interpréter une courbe de croissance","q":"Quelles sont les étapes clés pour lire et interpréter une courbe de croissance dans le cadre d'une évaluation pubertaire ?","a":"<ul><li>Suivre la <strong>position</strong> (couloir DS) et la <strong>pente</strong> (vitesse de croissance) de la courbe.</li><li>Comparer la taille de l'enfant à la <strong>taille cible génétique</strong>, calculée comme (taille père + taille mère) / 2, avec une marge de ± 6,5 cm selon le sexe.</li><li>Rechercher une éventuelle <strong>cassure de la courbe</strong>, pouvant indiquer une puberté pathologique, endocrinienne ou organique.</li></ul>"},{"i":"680882a1eaa2","n":49,"o":"49-11","u":"Diagnostic positif","t":"Savoir interpréter une courbe de croissance","q":"Comment interpréter la vitesse de croissance en cas de puberté précoce ou tardive ?","a":"<ul><li>En cas de <strong>puberté précoce</strong>, il y a une <strong>accélération</strong> de la vitesse de croissance, supérieure à <strong>9 cm/an</strong>.</li><li>En cas de <strong>puberté tardive</strong>, la vitesse de croissance reste celle de l'enfance, sans pic pubertaire.</li></ul>"},{"i":"8abb3ebf517f","n":49,"o":"49-11","u":"Diagnostic positif","t":"Savoir interpréter une courbe de croissance","q":"Quelle est l'importance de la courbe de croissance dans le diagnostic des pubertés pathologiques ?","a":"<p>La courbe de croissance est l'<strong>outil-pivot</strong> du diagnostic pubertaire, permettant d'identifier une puberté précoce ou tardive.</p>"},{"i":"9a0701294a36","n":49,"o":"49-11","u":"Diagnostic positif","t":"Savoir interpréter une courbe de croissance","q":"Quel est l'impact pronostique sur la taille adulte en cas de puberté précoce ou tardive ?","a":"<ul><li>Une <strong>puberté précoce</strong> expose à un risque de <strong>petite taille définitive</strong> due à la fusion précoce des cartilages de croissance.</li><li>Une <strong>puberté tardive</strong> expose également à un risque de <strong>petite taille définitive</strong> en l'absence de pic de croissance.</li></ul>"},{"i":"0e70e69f6cdd","n":49,"o":"49-16","u":"Diagnostic positif","t":"Définir le retard pubertaire du garçon et de la fille","q":"Quelle est la particularité de la vitesse de croissance chez un enfant présentant un retard pubertaire ?","a":"<p>La vitesse de croissance chez un enfant en retard pubertaire <strong>reste celle de l'enfance</strong>, sans l'apparition du pic pubertaire. Cela entraîne un <strong>risque de petite taille définitive</strong>.</p>"},{"i":"3d9d020aaba9","n":49,"o":"49-16","u":"Diagnostic positif","t":"Définir le retard pubertaire du garçon et de la fille","q":"Comment définit-on un retard pubertaire chez la fille, selon les critères de l'EDN ?","a":"<p>Un retard pubertaire chez la fille se définit par l'<strong>absence de développement mammaire après 13 ans</strong>.</p>"},{"i":"7f419ad3267c","n":49,"o":"49-16","u":"Diagnostic positif","t":"Définir le retard pubertaire du garçon et de la fille","q":"Comment définit-on un retard pubertaire chez le garçon, selon les critères de l'EDN ?","a":"<p>Un retard pubertaire chez le garçon se définit par l'<strong>absence de développement testiculaire après 14 ans</strong>.</p>"},{"i":"8302eeba84fa","n":49,"o":"49-16","u":"Diagnostic positif","t":"Définir le retard pubertaire du garçon et de la fille","q":"Quel est le critère commun de retard pubertaire, indépendant du sexe, mentionné dans le cours de l'EDN ?","a":"<p>Le critère commun de retard pubertaire est l'<strong>absence d'achèvement de la puberté 4 ans après son début</strong>.</p>"},{"i":"06813bab77c1","n":49,"o":"49-17","u":"Diagnostic positif","t":"Connaître les données de l'interrogatoire et de l'examen clinique en faveur d'un retard pubertaire","q":"Quels antécédents personnels sont pertinents à investiguer chez un patient présentant un potentiel retard pubertaire ?","a":"<p>On s'intéresse aux antécédents personnels suivants :</p><ul><li>Un <strong>ralentissement de la croissance</strong>.</li><li>Des <strong>maladies chroniques</strong> telles que la maladie cœliaque, les MICI (Maladies Inflammatoires Chroniques de l'Intestin), ou l'IRC (Insuffisance Rénale Chronique).</li><li>Une <strong>cryptorchidie</strong>, notamment bilatérale, chez le garçon.</li></ul>"},{"i":"1f21b4755996","n":49,"o":"49-17","u":"Diagnostic positif","t":"Connaître les données de l'interrogatoire et de l'examen clinique en faveur d'un retard pubertaire","q":"Quels symptômes associés doit-on rechercher à l'interrogatoire en cas de suspicion de retard pubertaire ?","a":"<p>Il faut rechercher les symptômes associés suivants :</p><ul><li>Des <strong>signes visuels</strong> ou des <strong>signes d'HTIC</strong> (Hypertension Intracrânienne).</li><li>Des <strong>signes d'autres atteintes hypothalamo-hypophysaires</strong> (ex: diabète insipide).</li><li>Une <strong>anosmie/hyposmie</strong>, forte évocatrice d'un <strong>syndrome de Kallmann</strong>.</li><li>Des <strong>signes digestifs</strong> comme une anorexie ou des douleurs abdominales, pouvant orienter vers une <strong>maladie cœliaque</strong> ou des <strong>MICI</strong>.</li></ul>"},{"i":"3e8618192192","n":49,"o":"49-17","u":"Diagnostic positif","t":"Connaître les données de l'interrogatoire et de l'examen clinique en faveur d'un retard pubertaire","q":"Quels sont les éléments clés de l'examen physique à réaliser pour un diagnostic de retard pubertaire ?","a":"<p>L'examen physique doit inclure :</p><ul><li>La <strong>cotation du stade pubertaire selon Tanner</strong>.</li><li>La recherche d'un <strong>syndrome dysmorphique</strong> (ex: syndrome de Turner, syndrome de Klinefelter).</li><li>L'<strong>examen des OGE</strong> (Organes Génitaux Externes) pour rechercher une cryptorchidie ou un micropénis.</li><li>L'évaluation de l'<strong>état nutritionnel</strong> (dénutrition, anorexie).</li><li>Un <strong>examen complet</strong>, en particulier <strong>neurologique</strong>.</li></ul>"},{"i":"570135affc6a","n":49,"o":"49-17","u":"Diagnostic positif","t":"Connaître les données de l'interrogatoire et de l'examen clinique en faveur d'un retard pubertaire","q":"Quels sont les antécédents familiaux à rechercher spécifiquement lors de l'interrogatoire d'un patient suspect de retard pubertaire ?","a":"<p>Il est important de rechercher :</p><ul><li>Les <strong>âges de début pubertaire des parents et de la fratrie</strong>.</li><li>L'<strong>âge de ménarche</strong> chez la mère.</li><li>Les <strong>tailles des parents</strong> pour estimer la taille cible génétique.</li><li>Une <strong>infertilité familiale</strong>.</li><li>Des <strong>troubles de l'odorat</strong> associés ou non à un trouble pubertaire, évoquant un syndrome de Kallmann.</li></ul>"},{"i":"69d201bd3a6b","n":49,"o":"49-19","u":"Étiologies","t":"Connaître les 2 grands cadres étiologiques des retards pubertaires : origines hypothalamo-hypophysaire ou gonadique","q":"Comment différencier un retard pubertaire central d'un retard pubertaire périphérique selon leur mécanisme et le bilan hormonal ?","a":"<p>Un <strong>retard pubertaire central</strong> est dû à une atteinte hypothalamo-hypophysaire, entraînant des taux de <strong>FSH et LH bas</strong> (hypogonadisme hypogonadotrope).<br>Un <strong>retard pubertaire périphérique</strong> est lié à une atteinte primitive des gonades, provoquant des taux de <strong>FSH et LH élevés</strong> en raison de la perte du rétrocontrôle négatif (hypogonadisme hypergonadotrope).</p>"},{"i":"82562eeee2ab","n":49,"o":"49-19","u":"Étiologies","t":"Connaître les 2 grands cadres étiologiques des retards pubertaires : origines hypothalamo-hypophysaire ou gonadique","q":"Quelles sont les causes à rechercher devant un retard pubertaire périphérique (hypogonadisme hypergonadotrope), et quels examens clés sont associés ?","a":"<p>Les causes d'un retard pubertaire périphérique incluent :</p><ul><li>Des <strong>causes acquises</strong> : Antécédents de chimiothérapie ou de radiothérapie pelvienne, ou insuffisance ovarienne auto-immune.</li><li>Des <strong>causes constitutionnelles</strong> : <strong>Syndrome de Turner</strong> (♀, caryotype <strong>45,X ou mosaïque</strong>) et <strong>Syndrome de Klinefelter</strong> (♂, caryotype <strong>47,XXY</strong>).</li></ul><p>Un <strong>caryotype systématique</strong> est l'examen clé devant toute suspicion de retard pubertaire périphérique.</p>"},{"i":"c404e5b401b9","n":49,"o":"49-19","u":"Étiologies","t":"Connaître les 2 grands cadres étiologiques des retards pubertaires : origines hypothalamo-hypophysaire ou gonadique","q":"Comment caractériser le Syndrome de Turner et le Syndrome de Klinefelter en termes de tableau clinique et de prise en charge diagnostique ?","a":"<ul><li>Le <strong>Syndrome de Turner (45,X)</strong> chez la fille se caractérise par une <strong>petite taille</strong>, des dysmorphies (cou palmé, cubitus valgus, écartement mamelonnaire), une <strong>insuffisance ovarienne</strong> (absence de puberté, infertilité), et des anomalies cardiovasculaires (coarctation de l'aorte / bicuspidie aortique). Un <strong>caryotype systématique</strong> est réalisé devant toute petite taille de la fille, même sans signe clinique.</li><li>Le <strong>Syndrome de Klinefelter (47,XXY)</strong> chez le garçon se manifeste par une <strong>grande taille eunuchoïde</strong> (membres longs), une <strong>gynécomastie fréquente</strong>, des signes pubertaires présents mais des <strong>testicules petits (&lt; 35 mm)</strong>, conduisant à une azoospermie et une infertilité.</li></ul>"},{"i":"d70c9dd8c69a","n":49,"o":"49-19","u":"Étiologies","t":"Connaître les 2 grands cadres étiologiques des retards pubertaires : origines hypothalamo-hypophysaire ou gonadique","q":"Quelles sont les causes à rechercher devant un retard pubertaire central (hypogonadisme hypogonadotrope) ?","a":"<p>Les causes d'un retard pubertaire central incluent :</p><ul><li>Des <strong>causes acquises</strong> : Tumeurs hypothalamo-hypophysaires (ex: <strong>craniopharyngiome</strong>, adénome), causes fonctionnelles (dénutrition, sport intensif, manque de sommeil, maladies chroniques).</li><li>Des <strong>causes constitutionnelles</strong> : <strong>Syndrome de Kallmann</strong> (associé à une anosmie/hyposmie), hypogonadisme hypogonadotrope isolé sans trouble olfactif, ou exprimé avec cryptorchidie bilatérale ou micropénis.</li></ul>"},{"i":"4487bd5258d1","n":49,"o":"49-2","u":"Définition","t":"Définir les termes suivants pubarche, thélarche et ménarche","q":"Quelle est la définition de la thélarche et son repère d'âge ?","a":"<p>La thélarche correspond à l'<strong>apparition du bourgeon mammaire chez la fille</strong>, signe du début de la puberté féminine. Elle est secondaire aux œstrogènes, sous contrôle de la LH et de la FSH. Le repère d'âge est entre <strong>8 et 13 ans</strong>.</p>"},{"i":"7dee64c7676a","n":49,"o":"49-2","u":"Définition","t":"Définir les termes suivants pubarche, thélarche et ménarche","q":"Quelle est la définition de la pubarche et son repère d'âge ?","a":"<p>La pubarche est l'<strong>apparition de la pilosité pubienne</strong>, chez la fille comme chez le garçon. Elle est liée à la production d'androgènes gonadiques et surrénaliens. Le repère d'âge est approximativement entre <strong>10 et 12 ans</strong>.</p>"},{"i":"951e38283d85","n":49,"o":"49-2","u":"Définition","t":"Définir les termes suivants pubarche, thélarche et ménarche","q":"Quelle est la définition de la ménarche et son repère d'âge par rapport à la thélarche ?","a":"<p>La ménarche correspond à la <strong>survenue des premières règles</strong> chez la fille. Elle survient environ <strong>2 ans après la thélarche</strong>, avec un repère d'âge d'environ <strong>12,5 ans</strong>.</p>"},{"i":"604189c10000","n":49,"o":"49-25","u":"Examens complémentaires","t":"Connaître l'objectif de l'échographie pelvienne et de la radiographie de la main et du poignet dans une puberté pathologique","q":"Quel est l'objectif de la radiographie de la main et du poignet dans l'exploration d'une puberté pathologique ?","a":"<p>La radiographie de la main et du poignet a pour objectif d'évaluer l'<strong>âge osseux</strong> selon la méthode de <strong>Greulich-Pyle</strong>. Elle permet de le comparer à l'âge civil pour détecter une avance (puberté précoce) ou un retard (retard pubertaire), et de repérer l'apparition du <strong>sésamoïde du pouce</strong>, signe du démarrage pubertaire (<strong>11 ans chez la fille / 13 ans chez le garçon</strong>). Enfin, elle aide à évaluer le pronostic statural.</p>"},{"i":"99bacc23bfe3","n":49,"o":"49-25","u":"Examens complémentaires","t":"Connaître l'objectif de l'échographie pelvienne et de la radiographie de la main et du poignet dans une puberté pathologique","q":"Quel est l'objectif de l'échographie pelvienne dans l'exploration d'une puberté pathologique chez la fille ?","a":"<p>L'échographie pelvienne chez la fille a principalement pour objectifs :</p><ul><li>D'<strong>éliminer un processus tumoral ovarien ou utérin</strong>.</li><li>D'apprécier l'<strong>imprégnation œstrogénique</strong> par l'apparition d'une <strong>ligne de vacuité de l'endomètre</strong> et une augmentation de la longueur du corps utérin (<strong>> 35 mm</strong>).</li></ul>"},{"i":"13b0de9c7223","n":49,"o":"49-9","u":"Définition","t":"Définir la puberté précoce et la puberté avancée","q":"Qu'est-ce qu'une puberté avancée chez la fille selon la définition de l'EDN ?","a":"<p>On parle de puberté avancée chez la fille lorsque le développement mammaire survient <strong>entre 8 et 10 ans</strong>. Ce phénomène est considéré comme <strong>non pathologique</strong>.</p>"},{"i":"5777a6d6742f","n":49,"o":"49-9","u":"Définition","t":"Définir la puberté précoce et la puberté avancée","q":"Comment définit-on une puberté précoce chez la fille ?","a":"<p>Une puberté est définie comme précoce chez la fille par un développement mammaire (thélarche) qui survient <strong>avant l'âge de 8 ans</strong>.</p>"},{"i":"5b7f848edf02","n":49,"o":"49-9","u":"Définition","t":"Définir la puberté précoce et la puberté avancée","q":"Comment est caractérisée la puberté précoce chez le garçon ?","a":"<p>La puberté précoce chez le garçon est définie par un développement testiculaire qui intervient <strong>avant l'âge de 9 ans</strong>. Ce développement peut être unilatéral.</p>"},{"i":"6402e161f028","n":49,"o":"49-9","u":"Définition","t":"Définir la puberté précoce et la puberté avancée","q":"Quelle est la définition d'une puberté avancée chez le garçon ?","a":"<p>Une puberté avancée chez le garçon se caractérise par un développement testiculaire survenant <strong>entre 9 et 11 ans</strong>. Ce cas de figure est considéré comme <strong>non pathologique</strong>.</p>"}]};